llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "In cirrhotic patients, pentoxifylline absolute bioavailability was 0.71 ± 0.24 after a 400 mg sustained-release tablet, directly supporting F ≥ 20% under the query condition."
    },
    {
      "card_ids": ["C24"],
      "claim": "Temozolomide pharmacokinetic studies concluded 100% oral bioavailability, supporting high oral bioavailability."
    },
    {
      "card_ids": ["C54"],
      "claim": "Pentoxifylline absolute bioavailability in healthy subjects averaged 20–30%, a low-F record that conflicts with the cirrhotic-patient result and is less condition-matched."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C54"],
  "decision_summary": "High is supported by direct cirrhosis-matched pentoxifylline F=71% and by multiple high absolute bioavailability records (e.g., temozolomide 100%); the healthy-volunteer low pentoxifylline record is outweighed by condition match.",
  "evidence_gaps": [
    "Only pentoxifylline provides direct evidence in cirrhosis; other evidence molecules were studied in healthy volunteers or general patients.",
    "Pentoxifylline has conflicting low-F records in healthy volunteers, adding uncertainty to cross-condition transfer."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C46", "C24"],
  "revision_action": "initial",
  "supportive_card_ids": ["C46", "C24"]
}

